using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "AppSettings", MimeType = "application/json")]
    [Description("Returns the application configuration settings.")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxConnections = 100,
            Features = new { Logging = true, Caching = true, RateLimiting = false }
        };

        return System.Text.Json.JsonSerializer.Serialize(config, new System.Text.Json.JsonSerializerOptions
        {
            WriteIndented = true
        });
    }

    [McpServerResource(UriTemplate = "config://app/endpoints", Name = "Endpoints", MimeType = "application/json")]
    [Description("Returns the available API endpoints and their descriptions.")]
    public static string GetEndpoints()
    {
        var endpoints = new[]
        {
            new { Path = "/mcp", Method = "POST", Description = "MCP Streamable HTTP endpoint" },
            new { Path = "/health", Method = "GET", Description = "Health check" }
        };

        return System.Text.Json.JsonSerializer.Serialize(endpoints, new System.Text.Json.JsonSerializerOptions
        {
            WriteIndented = true
        });
    }
}
